import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.foundation.lazy.rememberLazyListState
import androidx.compose.material3.*
import androidx.compose.runtime.*
import org.burnoutcrew.reorderable.*
@Composable
fun R(){
  var items by remember{mutableStateOf(List(8){"row $it"})}
  val st=rememberReorderableLazyListState(onMove={f,t->items=items.toMutableList().apply{add(t.index,removeAt(f.index))}})
  LazyColumn(state=st.listState,modifier=androidx.compose.ui.Modifier.reorderable(st).detectReorderAfterLongPress(st)){items(items,key={it}){x->ReorderableItem(st,key=x){_->ListItem(headlineContent={Text(x)})}}}}
